mapper.select:
SELECT TIME_CODE AS TIMECODE
FROM TB_TIME
WHERE TIME_CODE BETWEEN '000' AND #{endTime}

SELECT COALESCE(COUNT(*), 0)
FROM TB_BRODCONTENTDETAIL A
WHERE A.BROD_CODE = #{brodCode}

    AND A.INTERVAL_SECTION = #{intervalSection}

AND A.ATCH_FILE_ID = #{atchFileId}

SELECT COALESCE(X.PLAY_TIME, 0) + C.PLAY_TIME
FROM
    (
        SELECT SUM(COALESCE(B.PLAY_TIME, 0)) AS PLAY_TIME
        FROM TB_BRODCONTENTDETAIL A
                 JOIN LETTNFILEDETAIL B ON A.ATCH_FILE_ID = B.ATCH_FILE_ID
        WHERE A.INTERVAL_SECTION = #{intervalSection}
          AND A.BROD_CODE = #{brodCode}
    ) X
        JOIN LETTNFILEDETAIL C ON C.ATCH_FILE_ID = #{atchFileId}

SELECT COALESCE(X.PLAY_TIME, 0) + COALESCE(CAST(E.PLAY_TIME AS INTEGER), 0) FROM ( SELECT SUM(B.PLAY_TIME) AS PLAY_TIME FROM ( SELECT SUM(COALESCE(CAST(B.PLAY_TIME AS INTEGER), 0)) AS PLAY_TIME FROM TB_BRODCONTENTDETAIL A JOIN LETTNFILEDETAIL B ON A.ATCH_FILE_ID = B.ATCH_FILE_ID WHERE CAST(A.INTERVAL_SECTION AS INTEGER) = CAST(#{intervalSection} AS INTEGER) AND A.BROD_CODE = #{brodCode}
UNION ALL
SELECT SUM(COALESCE(CAST(D.PLAY_TIME AS INTEGER), 0)) AS PLAY_TIME FROM TB_BRODIMSI C JOIN LETTNFILEDETAIL D ON C.ATCH_FILE_ID = D.ATCH_FILE_ID WHERE CAST(C.INTERVAL_SECTION AS INTEGER) = CAST(#{intervalSection} AS INTEGER) AND C.BROD_CODE = #{brodCode} ) B ) X JOIN LETTNFILEDETAIL E ON E.ATCH_FILE_ID = #{atchFileId}

SELECT PLAY_TIME
FROM LETTNFILEDETAIL
WHERE ATCH_FILE_ID = #{atchFileId}

SELECT COALESCE(COUNT(*), 0)
FROM TB_BRODCONTENTDETAIL A
WHERE 1=1
AND A.BROD_CODE = #{brodCode}

    AND A.INTERVAL_SECTION = #{intervalSection}

