mapper.delete:
DELETE FROM TB_BRODCONTENTDETAIL
WHERE BROD_CODE = #{brodCode}
  AND CAST(INTERVAL_SECTION AS INTEGER) > CAST(#{intervalSection} AS INTEGER)

DELETE FROM TB_BRODCONTENTDETAIL
WHERE BROD_SEQ IN
      (
        SELECT
            A.BROD_SEQ
        FROM TB_BRODCONTENTDETAIL A
        JOIN TB_BRODSCHEDULE B ON A.BROD_CODE = B.BROD_CODE AND B.BASIC_BROD_CODE = #{brodCode} AND A.BROD_CODE != #{brodCode}
        WHERE CONCAT(COALESCE(A.ATCH_FILE_ID, ''), COALESCE(A.INTERVAL_SECTION, ''), COALESCE(A.CONTENT_STARTDAY, ''), COALESCE(A.CONTENT_ENDDAY, ''), COALESCE(CAST(A.CONTENT_ORDER AS VARCHAR), ''))
            =
        (
        SELECT CONCAT(COALESCE(C.ATCH_FILE_ID, ''), COALESCE(C.INTERVAL_SECTION, ''), COALESCE(C.CONTENT_STARTDAY, ''), COALESCE(C.CONTENT_ENDDAY, ''), COALESCE(CAST(C.CONTENT_ORDER AS VARCHAR), ''))
        FROM TB_BRODCONTENTDETAIL C
        WHERE C.BROD_CODE = #{brodCode}
                AND C.BROD_SEQ = #{brodSeq}
        )
    )
